style.css:
@-moz-document domain("discord.com") {
body::before {
    content: "";
    position: fixed;
    top: 0; left: 0;
    width: 100vw;
    height: 100vh;
    background: url("https://preview.redd.it/made-this-dexter-pc-wallpaper-wanted-to-share-it-v0-vpphyhydmzbe1.png?auto=webp&s=8c25672d2806443ae9038287de01c27b5f5feec6") no-repeat center center fixed;
    background-size: cover;
    z-index: -3;
    opacity: 0.8;
  }

  /* Kan efekti – üstte overlay olarak */
  body::after {
    content: "";
    position: fixed;
    top: 0; left: 0;
    width: 100vw;
    height: 100vh;
    background: url("https://www.transparenttextures.com/patterns/blood-splatter.png"),
                url("https://i.imgur.com/4zXb0cM.png");
    background-repeat: no-repeat, no-repeat;
    background-position: top left, bottom right;
    background-size: 400px, 600px;
    z-index: -2;
    opacity: 0.4;
    pointer-events: none;
  }

  /* Şeffaflık ve yazı düzeni devam */
  .container-2cd8Mz, .chat-2ZfjoI, .membersWrap-3NUR2t,
  .channels-3g2vYe, .chatContent-3KubbW,
  .sidebar-1tnWFu, .panels-3wFtMD {
    background-color: rgba(0, 0, 0, 0.6) !important;
    backdrop-filter: blur(4px);
  }

  .textArea-2CLwUE, .slateTextArea-1Mkdgw {
    background-color: rgba(0, 0, 0, 0.3) !important;
    border: 1px solid #ff0000 !important;
    color: #fff !important;
    text-shadow: 0 0 3px red;
  }

  .markup-2BOw-j, .channelName-3KPsGw, .title-29uC1r,
  .username-h_Y3Us, .nameTag-2EnNhj, .messageContent-2qWWxC {
    color: #ffffff !important;
    text-shadow: 0 0 4px #ff0000, 0 0 8px #ff0033 !important;
  }

  /* Butonlar */
  button, .button-14-BFJ, .lookFilled-1Gx00P {
    background-color: rgba(0, 0, 0, 0.2) !important;
    border: 1px solid #ff0000 !important;
    color: #ff0000 !important;
    box-shadow: 0 0 12px #ff0000 !important;
    text-shadow: 0 0 4px #ff0000 !important;
  }

  button:hover {
    background-color: rgba(255, 0, 0, 0.15) !important;
    box-shadow: 0 0 20px #ff0033 !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 8px;
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background-color: rgba(255, 0, 0, 0.4);
    border-radius: 10px;
  }
}
